import{_ as o,r as t,o as i,c as r,e as a,a as l,s as h}from"./chunks/framework.CXcwiNg-.js";const k=JSON.parse(`{"title":"Understanding Themes - October CMS User Guide","titleTemplate":false,"description":"Create a theme to hold your site's pages, layouts, and assets","frontmatter":{"subtitle":"Create a theme to hold your site's pages, layouts, and assets"},"headers":[{"level":2,"title":"Navigate to the Theme Settings","slug":"navigate-to-the-theme-settings","link":"#navigate-to-the-theme-settings","children":[]},{"level":2,"title":"Create a New Blank Theme","slug":"create-a-new-blank-theme","link":"#create-a-new-blank-theme","children":[]},{"level":2,"title":"Activate Your Theme","slug":"activate-your-theme","link":"#activate-your-theme","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/editor/understanding-themes.md","filePath":"user-guide/quickstart/editor/understanding-themes.md"}`),d={name:"user-guide/quickstart/editor/understanding-themes.md"};function c(m,e,u,g,p,y){const n=t("pre-heading"),s=t("post-heading");return i(),r("div",null,[a(n),e[0]||(e[0]=l("h1",null,"Understanding Themes",-1)),a(s),e[1]||(e[1]=h(`<p>In October CMS, a <strong>theme</strong> is the folder that holds everything your visitors see: pages, layouts, partials, content blocks, and assets like CSS and JavaScript. Your site always has one active theme, and switching themes changes the entire look and feel without affecting your content.</p><p>A theme&#39;s folder structure looks like this:</p><pre class="dir-container"><code><p>├── themes
|   └── my-theme
|       ├── <code>pages</code>  <em>← individual pages, each with its own URL</em>
|       ├── <code>layouts</code>  <em>← shared page structures (header, footer)</em>
|       ├── <code>partials</code>  <em>← reusable template fragments</em>
|       ├── <code>content</code>  <em>← static content blocks, editable in the backend</em>
|       └── <code>assets</code>  <em>← CSS, JavaScript, images, and fonts</em></p>
</code></pre><p>You don&#39;t need to memorize this. You will learn each piece as we go. For now, let&#39;s create a theme.</p><h2 id="navigate-to-the-theme-settings"><a href="#navigate-to-the-theme-settings" class="header-anchor">#</a> Navigate to the Theme Settings</h2><ol><li>In the backend, go to <strong>Settings → Frontend Theme</strong>.</li><li>You will see any themes that are currently installed. A fresh installation includes a demo theme.</li></ol><h2 id="create-a-new-blank-theme"><a href="#create-a-new-blank-theme" class="header-anchor">#</a> Create a New Blank Theme</h2><ol><li>Click the <strong>Create a New Blank Theme</strong> button.</li><li>Enter the following: <ul><li><strong>Name</strong>: <code>My Theme</code></li><li><strong>Directory Name</strong>: <code>mytheme</code></li></ul></li><li>Click <strong>Create</strong>.</li></ol><p>Your new theme now appears in the list. It is an empty theme with no pages and no layouts, just an empty folder ready for you to build in.</p><h2 id="activate-your-theme"><a href="#activate-your-theme" class="header-anchor">#</a> Activate Your Theme</h2><ol><li>Find <strong>My Theme</strong> in the theme list.</li><li>Click the <strong>Activate</strong> button next to it.</li><li>Confirm the activation.</li></ol><p>Your site is now using your new blank theme. If you visit the frontend right now, you will see a blank page. That is expected. We haven&#39;t created any pages yet.</p><div class="custom-block aside"><p>The demo theme is still installed and you can switch back to it at any time. Switching themes does not delete anything.</p></div><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Your theme is created and active. Let&#39;s give it some structure. Continue to <a href="./creating-a-layout.html">Creating a Layout</a> to build the HTML skeleton that all your pages will share.</p>`,15))])}const f=o(d,[["render",c]]);export{k as __pageData,f as default};
